import React from 'react';
import { useHistory } from 'react-router-dom';
import Dashboard from '../components/Dashboard';

const Home: React.FC = () => {
    const history = useHistory();

    const features = [
        {
            title: 'Dataset Upload',
            description: 'Upload CSV or Parquet files with your network logs for analysis',
        },
        {
            title: 'ML Analysis',
            description: 'Advanced machine learning-powered intrusion detection',
        },
        {
            title: 'Real-time Threats',
            description: 'Identify and classify security threats instantly',
        },
    ];

    return (
        <div style={{ paddingTop: '64px', paddingBottom: '64px', minHeight: '100vh' }}>
            <div className="container">
                {/* Hero Section */}
                <div
                    style={{
                        marginBottom: '64px',
                        textAlign: 'center',
                        color: 'var(--text-primary)',
                    }}
                >
                    <h1
                        style={{
                            fontWeight: 'bold',
                            marginBottom: '16px',
                            fontSize: '2.5rem',
                            background: 'linear-gradient(135deg, #cc2936 0%, #e63946 100%)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            backgroundClip: 'text',
                        }}
                    >
                        Cybersecurity IDS
                    </h1>
                    <p
                        style={{
                            marginBottom: '32px',
                            opacity: 0.9,
                            maxWidth: 600,
                            marginLeft: 'auto',
                            marginRight: 'auto',
                            fontSize: '1.125rem',
                            color: 'var(--text-secondary)',
                        }}
                    >
                        Advanced machine learning-powered analysis to detect and classify network intrusions
                    </p>
                    <div style={{ display: 'flex', gap: '16px', justifyContent: 'center', flexWrap: 'wrap' }}>
                        <button
                            className="btn btn-primary"
                            onClick={() => history.push('/upload')}
                            style={{
                                paddingLeft: '32px',
                                paddingRight: '32px',
                                fontSize: '1rem',
                            }}
                        >
                            Get Started
                        </button>
                        <button
                            className="btn btn-secondary"
                            onClick={() => history.push('/results')}
                            style={{
                                paddingLeft: '32px',
                                paddingRight: '32px',
                                fontSize: '1rem',
                            }}
                        >
                            View Results
                        </button>
                    </div>
                </div>

                {/* Features Section */}
                <div className="grid grid-3" style={{ marginBottom: '64px' }}>
                    {features.map((feature, index) => (
                        <div
                            key={index}
                            className="feature-card"
                            style={{
                                background: 'linear-gradient(135deg, rgba(204, 41, 54, 0.08) 0%, rgba(139, 21, 40, 0.04) 100%)',
                                border: '1px solid rgba(204, 41, 54, 0.2)',
                                color: 'var(--text-primary)',
                            }}
                        >
                            <h3 style={{ fontWeight: 'bold', marginBottom: '8px', color: 'var(--primary-red)' }}>
                                {feature.title}
                            </h3>
                            <p style={{ color: 'var(--text-secondary)' }}>
                                {feature.description}
                            </p>
                        </div>
                    ))}
                </div>

                {/* Dashboard Preview */}
                <div style={{ marginBottom: '32px' }}>
                    <h2
                        style={{
                            color: 'var(--text-primary)',
                            fontWeight: 'bold',
                            marginBottom: '24px',
                            background: 'linear-gradient(135deg, #cc2936 0%, #e63946 100%)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            backgroundClip: 'text',
                        }}
                    >
                        System Overview
                    </h2>
                    <div className="card">
                        <Dashboard />
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Home;
